generateOptimizationRecommendations() {
    console.log('\n💡 Import Optimization Recommendations:\n');

    const recommendations = [];

    // Analyze slow imports
    if (this.slowImports.length > 0) {
      console.log('🚨 Slow Imports Detected:');
      this.slowImports.forEach(imp => {
        console.log(`   ${imp.severity === 'CRITICAL' ? '🔴' : '🟡'} ${imp.module}: ${imp.time}ms`);

        if (imp.module.includes('database')) {
          recommendations.push({
            module: imp.module,
            issue: 'Database initialization overhead',
            solution: 'Move heavy database operations to lazy loading'
          });
        } else if (imp.module.includes('routers')) {
          recommendations.push({
            module: imp.module,
            issue: 'Router dependencies loading slowly',
            solution: 'Implement lazy router loading or reduce dependencies'
          });
        } else {
          recommendations.push({
            module: imp.module,
            issue: 'Heavy module initialization',
            solution: 'Profile and optimize module loading'
          });
        }
      });
    }

    console.log('\n🔧 Specific Recommendations:');
    recommendations.forEach((rec, index) => {
      console.log(`${index + 1}. ${rec.module}:`);
      console.log(`   Issue: ${rec.issue}`);
      console.log(`   Solution: ${rec.solution}\n`);
    });

    // General recommendations
    console.log('📈 General Performance Tips:');
    console.log('   • Use lazy imports for heavy dependencies');
    console.log('   • Implement module-level caching');
    console.log('   • Reduce circular dependencies');
    console.log('   • Profile with Python cProfile for detailed analysis');
  }
